    const requestId = document.getElementById('export-request-id').value.trim();
    if (requestId) params.set('request_id', requestId);
    for (const [key, elementId] of [['from', 'export-from'], ['to', 'export-to']]) {
      const raw = document.getElementById(elementId).value;
      if (raw) params.set(key, new Date(raw).toISOString());
    }
    const limitValue = document.getElementById('export-limit').value;
    params.set('limit', limitValue === '' ? '50' : String(parseInt(limitValue, 10)));
    message.className = '';
    message.textContent = '';
    preview.hidden = true;
    preview.textContent = '';
    button.disabled = true;
    try {
      const response = await fetch(`/api/releases/export?${params.toString()}`);
      const bodyText = await response.text();
      if (!response.ok) {
        let detail = '';
        try { detail = formatError(JSON.parse(bodyText), response.status); }
        catch (_) { detail = `请求失败（HTTP ${response.status}）`; }
        message.className = 'error';
        message.textContent = `导出失败：${detail}`;
        return;
      }
      if (format === 'json') {
        const records = JSON.parse(bodyText);
        message.className = 'success';
        message.textContent = records.length
          ? `已导出 ${records.length} 条发布记录，以下预览前 ${Math.min(10, records.length)} 条。`
          : '没有匹配的发布记录，导出结果为空。';
        preview.textContent = JSON.stringify(records.slice(0, 10), null, 2);
        preview.hidden = !records.length;
      } else {
        const lines = bodyText.split('\n').filter(line => line.length > 0);
        const count = Math.max(0, lines.length - 1);
        const blob = new Blob(['﻿' + bodyText], { type: 'text/csv;charset=utf-8' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = 'releases-export.csv';
        link.click();
        URL.revokeObjectURL(link.href);
        message.className = 'success';
        message.textContent = count
          ? `已下载 CSV 文件，共 ${count} 条发布记录。`
          : '没有匹配的发布记录，CSV 仅含表头。';
        preview.textContent = lines.slice(0, 11).join('\n');
        preview.hidden = false;
      }
    } catch (error) {
      message.className = 'error';
      message.textContent = `导出失败：${error.message}`;
    } finally {
      button.disabled = false;
    }
  });

  loadCatalog();
  refreshBudget();
  refreshHistory();
</script>

